// Helper function to get content for a specific subcategory
export const getSubcategoryContent = (categorySlug, subcategorySlug) => {
  // Handle nested subcategories (e.g., 'skin-treatment/skin-boosters')
  const normalizedSlug = subcategorySlug.replace(/\//g, '-');
  const key = `${categorySlug}-${normalizedSlug}`;

  // Check both main content and sub-subcategory content
  // Sub-subcategory content is already merged into subcategoryContent via spread operator
  return subcategoryContent[key] || null;
};

// Helper function to get all categories and subcategories
export const getAllSubcategories = () => {
  // Combine auto-generated services from pages folder + existing subcategoryContent
  const autoServices = autoGeneratedServices.map(key => {
    // Handle different key formats:
    // Format 1: "ayurveda-dubai-something" (has -dubai- in middle)
    // Format 2: "ayurvedic-diet-weight-loss-dubai" (has -dubai at end)
    // Format 3: "some-service" (no dubai)

    const parts = key.split('-dubai-');
    let category, subcategory;

    if (parts.length === 2) {
      // Format 1: ayurveda-dubai-something
      category = parts[0];
      subcategory = parts[1];
    } else if (key.endsWith('-dubai')) {
      // Format 2: ayurvedic-diet-weight-loss-dubai
      const withoutDubai = key.replace(/-dubai$/, '');
      const words = withoutDubai.split('-');
      category = words[0] || 'services';
      subcategory = words.slice(1).join('-');
    } else {
      // Format 3: some-service-name
      const words = key.split('-');
      category = words[0] || 'services';
      subcategory = words.slice(1).join('-');
    }

    return { category, subcategory, key };
  });

  // Also include any services from subcategoryContent that might not be in pages folder
  const contentServices = Object.keys(subcategoryContent).map(key => {
    const parts = key.split('-dubai-');
    let category, subcategory;

    if (parts.length === 2) {
      category = parts[0];
      subcategory = parts[1];
    } else {
      const [first, ...rest] = key.split('-');
      category = first;
      subcategory = rest.join('-');
    }

    return { category, subcategory, key };
  });

  // Merge and remove duplicates based on key
  const allServices = [...autoServices, ...contentServices];
  const uniqueKeys = new Set();
  const uniqueServices = allServices.filter(service => {
    if (uniqueKeys.has(service.key)) return false;
    uniqueKeys.add(service.key);
    return true;
  });

  return uniqueServices;
};

